var npcFilter = new flash.filters.GlowFilter(3407667,1,4,4,2,1,true,false);
this.npcPic.useHandCursor = false;
this.npcPic.onRollOver = function()
{
   mOver();
};
this.npcPic.onRollOut = function()
{
   mOut();
};
this.npcPic.onReleaseOutside = function()
{
   mOut();
};
this.npcPic.onRelease = function()
{
   this._parent.command();
};
this.mOver = function()
{
   this.npcPic.filters = [npcFilter];
};
this.mOut = function()
{
   this.npcPic.filters = [];
};
this.disappear();
var myTitle;
var myName;
var myID;
var words = "你好";
var answer = new Array();
var nextCmd;
var prevCmd;
this.appear = function(npc, toX, toY)
{
   myID = npc;
   myName = npc.name;
   myTitle = npc.nTitle;
   if(npc.jobLevels > 0)
   {
      npcName.text = npc.jobLevels + "级";
   }
   else
   {
      npcName.text = "";
   }
   npcName.text += myTitle + " " + myName;
   nameBack._width = 135 * npcName.text.length / 10;
   nameBack._x = -70 + (135 - nameBack._width) / 2;
   npcPic.gotoAndStop(myTitle);
   _X = toX;
   _Y = toY;
   _visible = true;
   nextCmd = npc.cmd;
};
this.disappear = function()
{
   _visible = false;
};
this.clearAnswer = function()
{
   answer = [];
};
this.openDialog = function()
{
   this._parent._parent.talking.open(this,this.words,this.answer);
};
this.closeDialog = function()
{
   this._parent._parent.talking.close();
};
this.setCommand = function(cmd)
{
   if(cmd == -1)
   {
      closeDialog();
      return undefined;
   }
   nextCmd = cmd;
   command();
};
this.command = function()
{
   this.clearAnswer();
   if(nextCmd >= 4000)
   {
      command2();
      return undefined;
   }
   var _loc7_;
   var _loc5_;
   switch(nextCmd)
   {
      case 0:
      default:
         switch(random(6))
         {
            case 0:
               words = _parent.role.myName + ",你好。";
               answer = [{txt:(myName != "" ? myName : myTitle) + ",你好",cmd:-1}];
               break;
            case 1:
               words = "呵呵";
               answer = [{txt:"呵呵",cmd:-1}];
               break;
            case 2:
               words = "祝你游戏愉快";
               answer = [{txt:"谢谢",cmd:-1}];
               break;
            case 3:
               words = "你好";
               answer = [{txt:"你好",cmd:-1}];
               break;
            case 4:
               words = "你已经" + _parent.role.levels + "级了啊";
               answer = [{txt:"是啊",cmd:-1}];
               break;
            case 5:
               words = "今天天气真不错";
               answer = [{txt:"恩......",cmd:-1}];
         }
         break;
      case 1:
         words = _parent.role.myName + ",你是新来的吧。我这里有些东西我已经用不上了,你挑几样去吧。";
         answer = [{txt:"嘿嘿,我不会客气的",cmd:2}];
         break;
      case 2:
         words = "哎,现在的年轻人真不懂礼貌。你挑一包去吧";
         words += "\r礼包一：上品+9武器、良品衣服、莎菲幻兽";
         words += "\r礼包二：雪瑞幻兽、灵魂礼包";
         words += "\r礼包三：圣天使雷斯幻兽、圣天使奈丽幻兽";
         answer = [{txt:"我要礼包一",cmd:3},{txt:"我要礼包二",cmd:4},{txt:"我要礼包三",cmd:5}];
         nextCmd = myID.cmd;
         break;
      case 3:
         words = "你已经获得了礼包一,祝你游戏愉快";
         answer = [{txt:"谢谢",cmd:-1}];
         myID.cmd = 6;
         _parent._parent.createThing({type:"莎菲"});
         if(_parent.role.vocational == "战士")
         {
            __weapon = {type:"武器",grade:2,name:"长军刀",mhdj:9,vocational:"战士",levels:1,minAttack:2,maxAttack:18,mMinAttack:1,mMaxAttack:9};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
            __weapon = {type:"衣服",grade:1,name:"锁环甲",mhdj:3,vocational:"战士",levels:1,defense:3,mDefense:1};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
            __weapon = {type:"头盔",grade:1,name:"蓝色深邃",mhdj:3,vocational:"战士",levels:1,defense:1,mDefense:1};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
            __weapon = {type:"鞋",grade:1,name:"野蛮行径",mhdj:3,vocational:"战士",levels:1,minAttack:1,maxAttack:6,mMinAttack:1,mMaxAttack:1};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
         }
         else
         {
            __weapon = {type:"武器",grade:2,name:"蛇杖",mhdj:9,vocational:"法师",levels:1,minAttack:9,maxAttack:14,mMinAttack:5,mMaxAttack:7};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
            __weapon = {type:"衣服",grade:1,name:"旅者装",mhdj:3,vocational:"法师",levels:1,defense:2,mDefense:1};
            _parent._parent.backPack.setThing(__weapon);
            __weapon = {type:"头盔",grade:1,name:"紫色占卜",mhdj:3,vocational:"法师",levels:1,defense:1,mDefense:1};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
            __weapon = {type:"鞋",grade:1,name:"虚幻圆舞",mhdj:3,vocational:"法师",levels:1,minAttack:3,maxAttack:5,mMinAttack:1,mMaxAttack:1};
            _parent._parent.upDataWeapon(__weapon);
            _parent._parent.backPack.setThing(__weapon);
         }
         nextCmd = myID.cmd;
         break;
      case 4:
         words = "你已经获得了礼包二,希望你能多多打BOSS";
         answer = [{txt:"谢谢",cmd:-1}];
         myID.cmd = 6;
         _parent._parent.createThing({type:"雪瑞"});
         _parent._parent.createThing({type:"灵魂礼包"});
         nextCmd = myID.cmd;
         break;
      case 5:
         words = "你已经获得了礼包三,接下来就看你的了,我相信你是个高手";
         answer = [{txt:"谢谢",cmd:-1}];
         myID.cmd = 6;
         _parent._parent.createThing({type:"圣天使雷斯"});
         _parent._parent.createThing({type:"圣天使奈丽"});
         nextCmd = myID.cmd;
         break;
      case 6:
         words = "如果你能拿得到2个勇士勋章给我,我可以给你一个月光宝盒。";
         answer = [{txt:"我已经拿来了",cmd:7},{txt:"是否有等级奖励",cmd:8},{txt:"我不想要",cmd:-1}];
         nextCmd = myID.cmd;
         break;
      case 7:
         nextCmd = myID.cmd;
         if(_parent._parent.backPack.useThing({type:"勇士勋章"},2) == true)
         {
            _parent._parent.createThing({type:"初级月光宝盒"});
            _global.sysMsg.addMsg("获得初级月光宝盒");
            closeDialog();
            return undefined;
         }
         words = "你的物品栏里没有2个勇士勋章啊。";
         answer = [{txt:"还是蒙不了你",cmd:-1}];
         break;
      case 8:
         nextCmd = myID.cmd;
         words = "每升10级可以来这里找我,我会送你一份礼物。";
         if(_root.upLevelPrize > 1)
         {
            words += "\r你已经领取了第" + (_root.upLevelPrize * 10 - 10) + "级的奖励了。";
         }
         answer = [{txt:"返回",cmd:myID.cmd},{txt:"知道了",cmd:-1}];
         if(_root.upLevelPrize < 6)
         {
            if(_root.upLevelPrize * 10 < _parent.role.levels)
            {
               words = "你可以领取第" + _root.upLevelPrize * 10 + "级的奖励,以下三样你选择一个吧。";
               words += "\r1.初级月光宝盒";
               words += "\r2.资源 50,000";
               words += "\r3.魔石 500";
               answer = [{txt:"我要初级月光宝盒",cmd:9},{txt:"我要资源",cmd:10},{txt:"我要魔石",cmd:11}];
            }
         }
         else if(_root.upLevelPrize < 11)
         {
            if(_root.upLevelPrize * 10 < _parent.role.levels)
            {
               words = "你可以领取第" + _root.upLevelPrize * 10 + "级的奖励,以下三样你选择一个吧。";
               words += "\r1.初级月光宝盒2个";
               words += "\r2.资源 100,000";
               words += "\r3.魔石 1000";
               answer = [{txt:"我要初级月光宝盒",cmd:12},{txt:"我要资源",cmd:13},{txt:"我要魔石",cmd:14}];
            }
         }
         else if(_root.upLevelPrize * 10 < _parent.role.levels)
         {
            words = "你可以领取第" + _root.upLevelPrize * 10 + "级的奖励,以下三样你选择一个吧。";
            words += "\r1.中级月光宝盒";
            words += "\r2.资源 200,000";
            words += "\r3.魔石 2000";
            answer = [{txt:"我要中级月光宝盒",cmd:15},{txt:"我要资源",cmd:16},{txt:"我要魔石",cmd:17}];
         }
         break;
      case 9:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent._parent.createThing({type:"初级月光宝盒"});
         _global.sysMsg.addMsg("获得 初级月光宝盒");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 10:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent.role.xxx_res += 50000;
         _global.sysMsg.addMsg("获得 50,000资源");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 11:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent.role.xxx_ms += 500;
         _global.sysMsg.addMsg("获得 500魔石");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 12:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent._parent.createThing({type:"初级月光宝盒"});
         _parent._parent.createThing({type:"初级月光宝盒"});
         _global.sysMsg.addMsg("获得 初级月光宝盒×2");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 13:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent.role.xxx_res += 50000;
         _global.sysMsg.addMsg("获得 100,000资源");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 14:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent.role.xxx_ms += 1000;
         _global.sysMsg.addMsg("获得 1,000魔石");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 15:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent._parent.createThing({type:"中级月光宝盒"});
         _global.sysMsg.addMsg("获得 中级月光宝盒");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 16:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent.role.xxx_res += 200000;
         _global.sysMsg.addMsg("获得 200,000资源");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 17:
         _root.upLevelPrize = _root.upLevelPrize + 1;
         _parent.role.xxx_ms += 2000;
         _global.sysMsg.addMsg("获得 2,000魔石");
         nextCmd = myID.cmd;
         closeDialog();
         return undefined;
      case 19:
         words = "呵呵,欢迎" + _parent.role.myName + "光临宝芝林魔域分店。";
         words += "\r作者叫我提示你,药品的使用方法：";
         words += "\r一、把药品拖到人物或幻兽的头像上点击。";
         words += "\r二、双击药品或者把药品放到快捷键栏上使用,这样使用会优先给去血最多的人或幻兽使用。";
         answer = [{txt:"好的,我想买点药",cmd:20},{txt:"谢谢,我点错人了",cmd:-1}];
         break;
      case 20:
         closeDialog();
         _parent._parent.drugShop.open();
         _parent._parent.backPack.openPanel();
         nextCmd = myID.cmd;
         return undefined;
      case 21:
         words = "......";
         answer = [{txt:"芝麻开门",cmd:22}];
         break;
      case 22:
         luckyBoss();
         closeDialog();
         disappear();
         return undefined;
      case 51:
         words = "我是军需官";
         answer = [{txt:"我需要一些药品",cmd:52},{txt:"帮我复活我的幻兽",cmd:53},{txt:"我要离开战场",cmd:54}];
         break;
      case 52:
         closeDialog();
         _parent._parent.drugShop.open();
         _parent._parent.backPack.openPanel();
         nextCmd = 51;
         return undefined;
      case 53:
         _parent.reLife();
         nextCmd = 51;
         closeDialog();
         return undefined;
      case 54:
         _parent.nextMap = _parent.oldCity;
         _parent.nextEntry = "backPoint";
         _parent.gotoAndStop(_parent.nextMap);
         return undefined;
      case 81:
         if(_parent.role.sex == "男")
         {
            words = "你好,小伙子";
         }
         else
         {
            words = "你好,小姑娘";
         }
         words += ",找我有什么事呢?";
         answer = [{txt:"我想制作幸运符",cmd:82},{txt:"我要和我的恋人结婚",cmd:86},{txt:"领取结婚戒指",cmd:89},{txt:"关于神兽药水",cmd:87},{txt:"路过...",cmd:-1}];
         break;
      case 82:
         if(_parent._parent.friend.lover == undefined)
         {
            words = "呵呵,等你有了恋人或爱人再来找我吧。";
            answer = [{txt:"好的",cmd:-1}];
            nextCmd = 81;
         }
         else
         {
            words = "难到你把的" + _parent._parent.friend.lover.relationName + _parent._parent.friend.lover.name + "给你的幸运符丢,我可以帮你再制作一个,但要收100魔石手工费的哦。";
            answer = [{txt:"恩,快帮我制作一个吧",cmd:83},{txt:"呵呵,没有丢,我只是随便问问",cmd:-1}];
            nextCmd = 81;
         }
         break;
      case 83:
         if(_parent.role.spendMs(100) == true)
         {
            if(_parent._parent.backPack.setThing({grade:0,name:(_parent._parent.friend.lover.sex != "女" ? "真理幸运符" : "永恒幸运符"),type:"幸运符",salePrice:100,loveName:_parent._parent.friend.lover.name,luckLevels:0,isFirstLove:_parent._parent.friend.isFirstLove}) == true)
            {
               _global.sysMsg.addMsg("获得物品 幸运符");
            }
            else
            {
               _global.sysMsg.addMsg("你的背包已满");
               _parent.goods.throwGoods(_X,_Y,{grade:0,name:(_parent._parent.friend.lover.sex != "女" ? "真理幸运符" : "永恒幸运符"),type:"幸运符",salePrice:100,loveName:_parent._parent.friend.lover.name,luckLevels:0,isFirstLove:_parent._parent.friend.isFirstLove});
            }
            words = "这是你的幸运符,以后可要保管好啊。";
            answer = [{txt:"知道啦,谢谢",cmd:-1}];
            nextCmd = 81;
         }
         else
         {
            words = "哎,你的魔石不够哦。";
            answer = [{txt:"啊,那我再去凑点吧",cmd:-1}];
            nextCmd = 81;
         }
         break;
      case 84:
         if(_parent._parent.friend.lover == undefined)
         {
            words = "玫瑰湖只向情侣开放,等你有了恋人或爱人再去吧。";
            answer = [{txt:"好的",cmd:-1}];
            nextCmd = 81;
         }
         else
         {
            words = "你想和你的" + _parent._parent.friend.lover.relationName + "一起到玫瑰湖赏景吗？那可是个非常美丽的地方哦,而且每次进去还可以获得一份礼物。";
            words += "\r    玫瑰湖门票 1,500磨石,确定去吗?";
            answer = [{txt:"是的,请送我们到玫瑰湖吧",cmd:85},{txt:"我觉得有点贵,还是算了吧",cmd:-1}];
            nextCmd = 81;
         }
         break;
      case 85:
         if(_parent.role.spendMs(1500) == true)
         {
            _parent.nextMap = "玫瑰湖";
            _parent.nextEntry = "entry1";
            _root.firstInto = true;
            _parent.gotoAndStop(_parent.nextMap);
            return undefined;
         }
         words = "哎,你的魔石不够哦。";
         answer = [{txt:"啊,那我再去凑点吧",cmd:-1}];
         nextCmd = 81;
         break;
      case 86:
         if(_parent._parent.friend.lover == undefined)
         {
            words = "你还没有恋人。";
            answer = [{txt:"嘿嘿,这都让你看出",cmd:-1}];
            nextCmd = 81;
         }
         else if(_parent._parent.friend.lover.relation < 1000)
         {
            words = "与恋人的亲密度达到1000的时候就才可以接任务。";
            answer = [{txt:"哦,那我过段时间再来",cmd:-1}];
            nextCmd = 81;
         }
         else if(_parent._parent.friend.lover.levels >= 5)
         {
            words = _parent._parent.friend.lover.name + "已经是你的爱人了。";
            answer = [{txt:"呵呵,随便问问的",cmd:-1}];
            nextCmd = 81;
         }
         else
         {
            words = "有情人终成眷属。";
            answer = [{txt:"哦,谢谢",cmd:-1}];
            nextCmd = 81;
            _parent._parent.friend.upToLover(_parent._parent.friend.lover);
         }
         break;
      case 87:
         nextCmd = myID.cmd;
         words = "神兽药水是一种很神秘的东西,我也不了解其中的奥秘。";
         answer = [{txt:"哦     ",cmd:-1}];
         if(_parent._parent.task.getTask("神兽药水任务二").isComplete == false)
         {
            words += "如果你能给我一只极品50星以上的幻兽,我就把这神兽药水送给你。";
            answer.unshift({txt:"给你50星的幻兽",cmd:88});
         }
         break;
      case 88:
         nextCmd = myID.cmd;
         closeDialog();
         _parent._parent.huanShou.openPanel();
         _parent._parent.giveHuanShou.open(this.getHuanShou50);
         return undefined;
      case 89:
         nextCmd = myID.cmd;
         if(_parent._parent.friend.lover == undefined || _parent._parent.friend.lover.relation < 1500)
         {
            words = "当你和爱人有亲密度到达1500时我会我送你一个戒指的。";
            answer = [{txt:"噢，我那我过几天再来",cmd:-1}];
         }
         else
         {
            words = "创造一个神圣的结婚戒指需要融入500亲密，你决定要一个戒指吗？";
            answer = [{txt:"是的，我决定了",cmd:90},{txt:"我还是考虑考虑吧",cmd:-1}];
