this.dropSoul = function(rnd, fX, fY, level)
{
   if(isNaN(rnd))
   {
      return false;
   }
   if(random(100) >= rnd)
   {
      return false;
   }
   var _loc5_ = 300;
   if(level > _loc5_)
   {
      level = _loc5_;
   }
   var _loc4_ = random(_root.devilSoul.length - 1) + 1;
   var _loc3_ = (_root.maxSoul[_loc4_] - _root.minSoul[_loc4_]) * level / _loc5_;
   _loc3_ *= 0.9 + Math.random() * 0.2;
   _loc3_ = Math.ceil(_loc3_);
   _parent.createThing({type:"宝石",name:"魔之魂",val1:_loc4_,val2:_loc3_},true,fX,fY);
};
