this.roleSkills.addSkill = function(skillName, reLv)
{
   var _loc2_;
   _loc2_ = this.allSkills.length - 1;
   while(_loc2_ >= 0)
   {
      if(this.allSkills[_loc2_].name == skillName)
      {
         if(this.allSkills[_loc2_].levels + 1 > this.allSkills[_loc2_].maxLevels)
         {
            return false;
         }
         if(this.allSkills[_loc2_].levels == 0)
         {
            this.allSkills[_loc2_].studied = true;
            this.studiedSkills = this.studiedSkills + 1;
            if(skillName == "震" || skillName == "怒")
            {
               this._parent.XPPower.isUsed = true;
            }
         }
         if(isNaN(reLv) == false)
         {
            this.allSkills[_loc2_].levels = reLv;
         }
         else
         {
            this.allSkills[_loc2_].levels++;
         }
         this.effect(skillName,this.allSkills[_loc2_].levels);
         this.afterAdd();
         return true;
      }
      _loc2_ = _loc2_ - 1;
   }
   return false;
};
this.roleSkills.afterAdd = function()
{
   this.maxPage = Math.floor((this.studiedSkills + 4) / 5);
   this.page.setPage();
   this.sortSkills();
   this.showSkills();
};
this.roleSkills.getSkill = function(skillName)
{
   var _loc2_;
   _loc2_ = this.allSkills.length - 1;
   while(_loc2_ >= 0)
   {
      if(this.allSkills[_loc2_].name == skillName)
      {
         return this.allSkills[_loc2_];
      }
      _loc2_ = _loc2_ - 1;
   }
   return null;
};
this.roleSkills.effect = function(skillName, levels)
{
   switch(skillName)
   {
      case "重伤":
         this.role.heavyDamage = levels;
         break;
      case "寒冰":
         this.role.frost = levels;
         break;
      case "神圣":
         this.role.skillAttack = 2 * levels;
         break;
      case "重击":
         this.role.heavyHit = 2 * levels;
         break;
      case "破防":
         this.role.nonDefense = 2 * levels;
         break;
      case "金刚":
         this.role.skillDefense = 8 * levels;
         break;
      case "强健之术":
         this.role.skillLife = 10 * this.role.rateLife * levels;
         break;
      case "智慧之术":
         this.role.skillMp = 10 * this.role.rateMp * levels;
         break;
      case "英勇":
         this.role.skillAddFire = 5 * levels;
         break;
      default:
         return false;
   }
   this.role.flashAttribute();
   return true;
};
this.roleSkills.sortSkills = function()
{
   this.allSkills.sortOn(["studied","condition"],[Array.DESCENDING | Array.NUMERIC,Array.DESCENDING | Array.NUMERIC]);
};
this.roleSkills.showSkills = function()
{
   var _loc2_;
   var _loc3_;
   _loc2_ = 1;
   while(_loc2_ <= 5)
   {
      if(this.allSkills[(this.nowPage - 1) * 5 + _loc2_ - 1].studied)
      {
         this["技能格" + _loc2_].showSkill(this.allSkills[(this.nowPage - 1) * 5 + _loc2_ - 1]);
      }
      else
      {
         this["技能格" + _loc2_].hideSkill();
      }
      _loc2_ = _loc2_ + 1;
   }
};
this.roleSkills.prePage = function()
{
   if(this.nowPage > 1)
   {
      this.nowPage = this.nowPage - 1;
      this.showSkills();
   }
};
this.roleSkills.nextPage = function()
{
   if(this.nowPage < this.maxPage)
   {
      this.nowPage = this.nowPage + 1;
      this.showSkills();
   }
};
